      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-xiaoke-widget\",\n  \"version\": \"0.4.2\",\n  \"description\": \"DSH Web 界面右下角的 Claude 拟人桌宠「小克」:余额/今日已用/峰谷定价、自定义泡泡点击序列(文本/余额/今日/峰谷/图片/随机语句与并列加权选择)、逐行样式与字体、悬浮快捷编辑、音效与每轮消耗、自定义角色/动图/音效、吸附与翻转自定义。二创自 MeteorNOX/DeepSeek-Balance-Whale-Widget (MIT)\",\n  \"keywords\": [\n    \"dsh\",\n    \"dsh-plugin\",\n    \"deepseek-harness\",\n    \"balance\",\n    \"widget\",\n    \"claude\",\n    \"mascot\",\n    \"xiaoke\"\n  ],\n  \"type\": \"module\",\n  \"main\": \"lib/xiaoke-index.js\",\n  \"icon\": \"./icon.png\",\n  \"files\": [\n    \"lib\",\n    \"assets\",\n    \"icon.png\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"PROVENANCE.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"node tools/build-xiaoke.mjs\",\n    \"check\": \"node tools/build-xiaoke.mjs --check\",\n    \"verify\": \"node tools/build-xiaoke.mjs --check && node --check lib/xiaoke-index.js && node --check lib/xiaoke-widget.js && node tools/verify-host-routes.mjs && node tools/verify-widget-exec.cjs\",\n    \"copy\": \"node tools/dump-copy.mjs --write\"\n  },\n  \"license\": \"MIT\"\n}\n"
